userscript.function:

            //if(sUtils.workflow.check('CT1661237936307')) { // 갑지 계약자 그리드 사용 모듈
            if (true) { // TODO: 갑지 그리드 사용 모듈 체크(추후 사용)
                targetObj = 'grid'

                const signOrderOption = sUtils.workflow.check('CT1688609027512') ? 'P' : 'S';
                const targetButton = btnObj_left.btn('SIGN_ORDER_' + signOrderOption);
                if (targetButton) {
                    targetButton._vp.prepend(targetButton._area.base);
                }
                setSignOrder(signOrderOption);

                formObj._parent.style.display = 'none';

                minSigner = <%= CommonUtil.getConfig("sepoa.contract.signer.min", "2")%>;
                maxSigner = <%= CommonUtil.getConfig("sepoa.contract.signer.max", "9")%>;
            } else {
                targetObj = 'form'
                container.style.display = 'none';
            }

            // 동아 순차서명, 동시서명 아이템 삭제
            btnObj_left.btn('SIGN_ORDER_S').setHide();
            btnObj_left.btn('SIGN_ORDER_P').setHide();

            //gridObj.setColumnHidden(gridObj.getColIndexById('CATEGORY'), 1);

            onReady();

            // 동아제약 커스텀문구 추가
			var customText = '';
            customText += '<div><br>1. 첫번째 칸은 동아ST의 계약자 정보를 입력합니다.<br>'
            customText += '2. 두번째 칸부터는 행추가하여 계약상대방의 계약자 정보를 입력합니다.</div>'
            var customHeader = gridFooterText;

            customHeader.appendChild($(customText)[0]);


callFunction('p', 'childScreenReady', [{
    name: 'SIGNNER',
    id: $sObject.aliasCode,
    fn: {
        doOpenDocument: doOpenDocument,
        doClear: doClear,
        doValidate: doValidate,
        setViewMode: setViewMode
    }
}])


if (targetObj == 'form') {
    formObj.setViewMode(flag);
} else if (targetObj == 'grid') {
    gridObj.setReadOnly(flag);

    btnObj_right.forEachBtn(id => {
        btnObj_right.showButton(id, !flag);
    });
}

$share.isReadOnly = flag;


if (!config) {
    return;
}

$share.config = config;

if (currentSignOrder) {
    if ($share.config && $share.config.data) {
        $share.config.data.SIGN_ORDER = currentSignOrder;
    }
}

if (targetObj == 'form') {
    formObj.dataMapper($share.config.data, "JSON");
} else if (targetObj == 'grid') {
    if ($share.config.data?.SIGNER) {
        loadGrid($share.config.data.SIGNER);
    } else {
        // 계약대상현황에서 넘어오지 않은 경우, 현재 로그인 사용자 정보 조회하여 첫 번째 행에 세팅
        // SCMGL 에 동아제약 정보가 정상적으로 등록되어야 있어야 한다.
        let so = doServiceAjax("sepoa.svc.ct.CT_201", 'CONNECTION', "doSelectSignerInfo", {}, function(so) {}, false);
        if(so.status == 1 && so.result && so.result.length > 0) {
            const signerData = JSON.parse(so.result[0]);
            // 첫 번째 행 추가
            const rowId = dhx.newId();
            gridObj.addRow(rowId, gridObj.getRowsNum());
            gridObj.cells(rowId, gridObj.getColIndexById('SEQ')).setValue(1);

            // 서명자 데이터 세팅
            for (let entry of Object.entries(signerData)) {
                const [key, value] = entry;
                const columnIndex = gridObj.getColIndexById(key);
                if (columnIndex) {
                    if (gridObj.getColType(columnIndex).includes('combo')) {
                        const isComboLoaded = gridObj._ajaxStatusW.combo == 0;
                        if (isComboLoaded === false) {
                            const eventId = gridObj.attachEvent('onComboLoaded', () => {
                                gridObj.cells(rowId, columnIndex).setValue(value);
                                gridObj.detachEvent(eventId);
                            })
                        } else {
                            gridObj.cells(rowId, columnIndex).setValue(value);
                        }
                    } else {
                        gridObj.cells(rowId, columnIndex).setValue(value);
                    }
                }
            }
        }
    }

    // 도급처 1행은 자동 세팅, 나머지 행은 추가
    for (let i = gridObj.getRowsNum(); i < minSigner; i++) {
        addGridRow();
    }

    // 모든 행 추가 후 $share.config.data.SIGNER에 반영
    setSignerData(gridObj.getAllDataObject());
}


if (targetObj == 'form') {
    formObj.clear();
} else if (targetObj == 'grid') {
    gridObj.clearAll();
}


const header = gridObj.getColumnId(cId);
if ($share.isReadOnly) {
    return false;
}

if (header == 'SIGNER_SEARCH') {
    const rowData = gridObj.getRowDataObject(rId);
    if (rowData.CATEGORY == '') {
        Alert(sUtils.cache.text.get('CT_205_B.MESSAGE_CHECK_CATEGORY')); // '계약자 구분을 선택해주세요.'
        return;
    }

    const options = {
        url: window.CONTEXT_NAME + '/Contract/setForm/ContractsetFormSignerPopup.sux',
        params: {
            CATEGORY: rowData.CATEGORY,
            callback: (data) => {
                const hasTarget = gridObj.getAllDataObject().filter(e => e.SIGNER_ID == data.SIGNER_ID).length > 0;
                if (hasTarget) {
                    const message = sUtils.string.dataReplacer(
                        sUtils.cache.text.get('CT_205_B.MESSAGE_ALREADY_ADDED_SIGNER'), // '$.{SIGNER_NAME} 님은 이미 계약자 목록에 추가되어있습니다.'
                        {
                            SIGNER_NAME: data.SIGNER_NAME
                        }
                    );

                    Alert(message);
                } else {
                    data.SEQ = rowData.SEQ;
                    addSigner(data)
                }
            }
        },
        width: SUX.getModuleTop().outerWidth * 0.6,
        height: SUX.getModuleTop().outerHeight * 0.5,
        title: sUtils.cache.text.get('CT_205_B_POPUP.TITLE') // '계약자 선택'
    };

    sUtils.popup.modal(options);
}


const limit = 1;
const cId = gridObj.getColumnId(cInd);
if (stage == 2) {
    if (cId == 'CATEGORY') {
        if (newValue == 'C') {
            const hasTargetValue = gridObj.getAllDataObject().filter(e => e.CATEGORY == 'C').length > limit;
            if (hasTargetValue) {
                Alert(sUtils.string.dataReplacer(sUtils.cache.text.get('CT_205_B.MESSAGE_SIGNER_LIMIT'), {
                    LIMIT: limit
                })); // '도급처 추가는 최대 $.{LIMIT} 개만 가능합니다.'
                return;
            }
        }

        /*
        const excludeKey = ['SELECTED', 'CATEGORY', 'SIGNER_SEARCH', 'SEQ'];
        for (let columnId of gridObj.columnIds) {
            if (excludeKey.includes(columnId) === false) {
                gridObj.cells(rId, gridObj.getColIndexById(columnId)).setValue('S');
            }
        }
        */
    }

    setSignerData(gridObj.getAllDataObject());
}

return true;


if (targetObj == 'form') {
    return formValidate();
} else if (targetObj == 'grid') {
    return gridValidate();
}

return true;


if (!formObj.validate()) {
    Alert(Sepoa.cache.text.get('CT_205.MSG7')); // '입력되지않은 서명대상자 정보가 존재합니다.'
    return false;
}

return true;


if (gridObj.getRowsNum() < minSigner) {
    const message = Sepoa.cache.text.get('CT_205_B.MESSAGE_REQUIRE_MIN_SIGNER'); // '최소 $.{MIN_SIGNER} 명 이상의 계약자 지정이 필요합니다.'
    Alert(sUtils.string.dataReplacer(message, {
        MIN_SIGNER: minSigner
    }));

    return false;
}

if (gridObj.getRowsNum() > maxSigner) {
    const message = Sepoa.cache.text.get('CT_205_B.MESSAGE_CHECK_MAX_SIGNER'); // '최대 $.{MAX_SIGNER} 명 까지만 계약자 지정이 가능합니다.'
    Alert(sUtils.string.dataReplacer(message, {
        MAX_SIGNER: maxSigner
    }));

    return false;
}

if (!gridObj.validate()) {
    Alert(Sepoa.cache.text.get('CT_205.MSG7')); // '입력되지않은 서명대상자 정보가 존재합니다.'

    return false;
}

return true;


if ($share.isReadOnly) {
    return;
}
if (id == 'VENDOR_SEARCH') {
    PopupCommonPost('SP0060', function(code, company, irs_no, ceo_name, addr) {
        formObj.setValue('SELLER_CODE', code, true);
        formObj.setValue('SELLER_NAME', company, true);
        formObj.setValue('SELLER_IRS_NO', irs_no, true);
        formObj.setValue('SELLER_CEO_NAME', ceo_name, true);
        formObj.setValue('SELLER_ADDR', addr);
    }, [Sepoa.info.HOUSE_CODE, Sepoa.info.COMPANY_CODE]);
} else if (id == 'BUYER_USER_SEARCH') {
    PopupCommonPost('SP0061', function(id, name, email, tel) {
        formObj.setValue('BUYER_USER_ID', id, true);
        formObj.setValue('BUYER_USER_NAME', name, true);
        formObj.setValue('BUYER_USER_EMAIL', email, true);
        formObj.setValue('BUYER_USER_TEL', tel);
    }, [Sepoa.info.HOUSE_CODE, formObj.getValue('BUYER_CODE')]);
} else if (id == 'SELLER_USER_SEARCH') {
    PopupCommonPost('SP0063', function(id, name, email, tel) {
        formObj.setValue('SELLER_USER_ID', id, true);
        formObj.setValue('SELLER_USER_NAME', name, true);
        formObj.setValue('SELLER_USER_EMAIL', email, true);
        formObj.setValue('SELLER_USER_TEL', tel);
    }, [Sepoa.info.HOUSE_CODE, formObj.getValue('SELLER_CODE')]);
}


if ($share.isReadOnly === true) {
    return;
}

switch (id) {
    case 'ADD':
        addGridRow();

        break;
    case 'DELETE':
        deleteGridRow();

        break;
    default:
        break;
}


if (gridObj.getRowsNum() + 1 > maxSigner) {
    const message = Sepoa.cache.text.get('CT_205_B.MESSAGE_CHECK_MAX_SIGNER'); // '최대 $.{MAX_SIGNER} 명 까지만 계약자 지정이 가능합니다.'
    Alert(sUtils.string.dataReplacer(message, {
        MAX_SIGNER: maxSigner
    }));

    return false;
}

const rowId = dhx.newId();
gridObj.addRow(rowId, gridObj.getRowsNum());

gridObj.cells(rowId, gridObj.getColIndexById('SEQ')).setValue(gridObj.getRowsNum());
//gridObj.cells(rowId, gridObj.getColIndexById('CATEGORY')).setValue('S');
const categoryColIdx = gridObj.getColIndexById('CATEGORY');
if (gridObj.getColType(categoryColIdx).includes('combo')) {
    const isComboLoaded = gridObj._ajaxStatusW.combo == 0;
    if (isComboLoaded === false) {
        // 콤보 데이터가 아직 로딩 중이라면, 로딩 완료 이벤트(onComboLoaded) 발생 시 값 세팅
        const eventId = gridObj.attachEvent('onComboLoaded', () => {
            gridObj.cells(rowId, categoryColIdx).setValue('S');
            gridObj.detachEvent(eventId);
        });
    } else {
        // 이미 로딩이 완료된 상태라면 즉시 세팅
        gridObj.cells(rowId, categoryColIdx).setValue('S');
    }
} else {
    gridObj.cells(rowId, categoryColIdx).setValue('S');
}

setSignerData(gridObj.getAllDataObject());


const signerList = $share.config.data.SIGNER;
for (let rowId of gridObj.getGridChangedRows('SELECTED')) {
    gridObj.deleteRow(rowId);
}

sortGridSeq();

setSignerData(gridObj.getAllDataObject());


if (!$share.config.data) {
    return;
}

if (!$share.config.data.SIGNER) {
    $share.config.data.SIGNER = [];
}

const rowId = gridObj.getRowId(data.SEQ - 1);
if (rowId) {
    for (let entry of Object.entries(data)) {
        const [key, value] = entry;
        const columnIndex = gridObj.getColIndexById(key);
        if (columnIndex) {
            if (gridObj.getColType(columnIndex).includes('combo')) {
                const isComboLoaded = gridObj._ajaxStatusW.combo == 0;
                if (isComboLoaded === false) {
                    const eventId = gridObj.attachEvent('onComboLoaded', () => {
                        gridObj.cells(rowId, columnIndex).setValue(value);
                        gridObj.detachEvent(eventId);
                    })
                }
            }

            gridObj.cells(rowId, columnIndex).setValue(value);
        }
    }
}

setSignerData(gridObj.getAllDataObject());


if (!$share.config.data) {
    return;
}

let tmp = [];
if ($share.config.data.SIGNER) {
    tmp = $share.config.data.SIGNER;
}

$share.config.data.SIGNER = [];
for (let signer of data) {
    const mergeData = sUtils.object.extend(true, {}, tmp.find(e => e.SIGNER_ID == signer.SIGNER_ID), parseSignerData(signer));
    $share.config.data.SIGNER.push(mergeData);
}


const ids = gridObj.getAllRowIds(',').split(',');
for (let i in ids) {
    const id = ids[i];
    gridObj.cells(id, gridObj.getColIndexById('SEQ')).setValue(Number(i) + 1);
}


if ($share.isReadOnly === true) {
    return;
}

// type : 'S' -> 순차 서명, 'P' -> 동시 서명
currentSignOrder = type;

if ($share.config && $share.config.data) {
    $share.config.data.SIGN_ORDER = currentSignOrder;
}

btnObj_left.forEachBtn(id => {
    const item = btnObj_left.btn(id);
    if (id == 'SIGN_ORDER_' + type) {
        item.setIcon('xi-radiobox-checked');
    } else {
        item.setIcon('xi-radiobox-blank');
    }
});

if (type == 'S') {
    gridObj.setColumnHidden(gridObj.getColIndexById('SEQ'), false);
} else {
    gridObj.setColumnHidden(gridObj.getColIndexById('SEQ'), true);
}


for (let signer of data) {
    const rowId = dhx.newId();
    gridObj.addRow(rowId, gridObj.getRowsNum());
    gridObj.cells(rowId, gridObj.getColIndexById('SEQ')).setValue(gridObj.getRowsNum());

    if (rowId) {
        for (let entry of Object.entries(signer)) {
            const [key, value] = entry;
            const columnIndex = gridObj.getColIndexById(key);
            if (columnIndex) {
                if (gridObj.getColType(columnIndex).includes('combo')) {
                    const isComboLoaded = gridObj._ajaxStatusW.combo == 0;
                    if (isComboLoaded === false) {
                        const eventId = gridObj.attachEvent('onComboLoaded', () => {
                            gridObj.cells(rowId, columnIndex).setValue(value);
                            gridObj.detachEvent(eventId);
                        })
                    }
                }

                gridObj.cells(rowId, columnIndex).setValue(value);
            }
        }
    }
}

setSignerData(data);
